        content.SizeChanged += (_, _) => FitArtwork(); record.SizeChanged += (_, _) => FitArtwork();
        var words = new Grid(); words.RowDefinitions.Add(new() { Height = GridLength.Auto }); words.RowDefinitions.Add(new() { Height = new GridLength(1, GridUnitType.Star) }); var tools = new LyricsToolbar(vm, true) { HorizontalAlignment = HorizontalAlignment.Right }; words.Children.Add(tools); Lyrics = new LyricsView(vm, true); Grid.SetRow(Lyrics, 1); words.Children.Add(Lyrics); Grid.SetColumn(words, 1); content.Children.Add(words);
