        SeekSlider = new PlaybackSeekSlider { ToolTip = "播放进度", VerticalAlignment = VerticalAlignment.Center }; progress.Children.Add(SeekSlider);
        var elapsed = Time("PositionText", HorizontalAlignment.Left); var duration = Time("DurationText", HorizontalAlignment.Right); Grid.SetRow(elapsed, 1); Grid.SetRow(duration, 1); progress.Children.Add(elapsed); progress.Children.Add(duration);
        var controls = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center }; var previous = MakeIcon("\uE892", "上一首", null, 42, 24); previous.Command = vm.PreviousCommand; previous.Margin = new Thickness(0, 0, 12, 0); controls.Children.Add(previous);
