orderBrushProperty, new DynamicResourceExtension("AccentBrush"), "PlaySurface")); playTemplate.Triggers.Add(focus); play.Template = playTemplate; controls.Children.Add(play);
        var next = MakeIcon("\uE893", "下一首", null, 42, 24); next.Command = vm.NextCommand; next.Margin = new Thickness(12, 0, 0, 0); controls.Children.Add(next); Grid.SetRow(controls, 1); footer.Children.Add(controls);
        var mode = MakeIcon("", "切换播放模式", null, 36, 20); mode.Command = vm.ModeCommand; mode.SetBinding(ContentProperty, new Binding("ModeIcon")); mode.SetBinding(ToolTipProperty, new Binding("ModeText")); mode.Margin = new Thickness(0, 0, 12, 0); controls.Children.Insert(0, mode);
        var favorite = MakeIcon("", "收藏 / 取消收藏", null, 36, 24); favorite.FontFamily = new FontFamily("Segoe UI Symbol"); favorite.Command = vm.FavoriteCommand; favorite.SetBinding(ContentProperty, new Binding("FavoriteGlyph")); favorite.SetResourceReference(ForegroundProperty, "AccentBrush"); favorite.Margin = new Thickness(12, 0, 0, 0); controls.Children.Add(favorite);
        var utilities = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, HorizontalAlignment = HorizontalAlignment.Right }; var mute = MakeIcon("\uE767", "静音", null, 36, 21); mute.Command = vm.MuteCommand; utilities.Children.Add(mute); var volume = new Slider { Minimum = 0, Maximum = 100, Width = 78, Margin = new Thickness(5, 0, 8, 0), VerticalAlignment = VerticalAlignment.Center, ToolTip = "音量" }; volume.SetBinding(RangeBase.ValueProperty, new Binding("Volume") { Mode = BindingMode.TwoWay }); utilities.Children.Add(volume);
