        var queueBody = new Grid(); queueBody.RowDefinitions.Add(new() { Height = GridLength.Auto }); queueBody.RowDefinitions.Add(new() { Height = new GridLength(1, GridUnitType.Star) }); var queueHeading = new TextBlock { FontSize = 13, FontWeight = FontWeights.SemiBold, Margin = new Thickness(2, 0, 0, 12) }; queueHeading.SetBinding(TextBlock.TextProperty, new Binding("Queue.Count") { Source = vm, StringFormat = "播放队列 · {0}" }); queueBody.Children.Add(queueHeading);
        var queueContent = UiFactory.ListWithEmptyState(QueueList, "队列为空", "添加歌曲后会显示在这里。"); Grid.SetRow(queueContent, 1); queueBody.Children.Add(queueContent);
