        QueuePopup = new Popup { Child = popupSurface, PlacementTarget = queue, Placement = PlacementMode.Top, AllowsTransparency = true, StaysOpen = false }; queue.Click += (_, _) => QueuePopup.IsOpen = !QueuePopup.IsOpen; QueuePopup.Opened += (_, _) => { QueueList.SelectedItem = vm.Current; if (vm.Current != null) QueueList.ScrollIntoView(vm.Current); };
        void PlaySelected() { if (QueueList.SelectedItem is Track track) { int index = vm.Queue.IndexOf(track); if (index >= 0) vm.Run(() => vm.PlayAsync(index)); } }
