    private static Button MakeIcon(string glyph, string tip, Action? action, double size, double font)
    {
        var button = new Button { Content = glyph, ToolTip = tip, Width = size, Height = size, Padding = new Thickness(0), Margin = new Thickness(0), FontSize = font }; button.SetResourceReference(StyleProperty, "IconButton"); if (action != null) button.Click += (_, _) => action(); return button;
    }
    private static TextBlock Time(string binding, HorizontalAlignment alignment) { var text = new TextBlock { FontSize = 11, HorizontalAlignment = alignment, VerticalAlignment = VerticalAlignment.Center }; text.SetBinding(TextBlock.TextProperty, new Binding(binding)); text.SetResourceReference(TextBlock.ForegroundProperty, "MutedBrush"); return text; }
